/* Existing browser-local range data, edited through the existing parent PIN portal. */
(function(root){'use strict';
function card(){return `<section class="card card-pad companion-preferences"><div class="eyebrow">PARENT SETTINGS · COMPANION VISUALS</div><h2>A range that fits your care plan</h2><p>Parent settings · mg/dL. These thresholds select buddy illustrations; a recent reading at or below low also interrupts optional waiting. They do not calculate treatment or notify caregivers. Changes require Save.</p><details class="parent-explanation"><summary>What does this mean?</summary><p>Low is at or below your low number; high is at or above your high number. Between them is in range. Missing, invalid or over-15-minute-old readings stay neutral. These are settings, not time-in-range statistics. Ask your care team about appropriate thresholds.</p></details><form id="parent-range-form"><div class="range-fields"><label>Low at or below (mg/dL)<input id="parent-range-low" type="number" min="20" max="599" value="${Number(state.thresholds.low)}" required></label><label>High at or above (mg/dL)<input id="parent-range-high" type="number" min="21" max="600" value="${Number(state.thresholds.high)}" required></label></div><label class="context-toggle"><input id="context-enabled" type="checkbox" ${state.contextualEmotes!==false?'checked':''}> Show brief contextual illustrations for recent connected readings</label><p class="helper">Sandbox readings are simulated. Stale, missing or invalid readings keep neutral behavior. No verified pump-event adapter is connected, so correction animations are unavailable.</p><p id="parent-range-error" role="status"></p><button class="primary">Save glucose thresholds &amp; visual preferences</button></form></section>`}
function bind(){const form=document.querySelector('#parent-range-form');if(!form)return;form.onsubmit=e=>{e.preventDefault();if(!root.parentPortalUnlocked?.())return;const low=Number(document.querySelector('#parent-range-low').value),high=Number(document.querySelector('#parent-range-high').value),status=document.querySelector('#parent-range-error');if(!Number.isInteger(low)||!Number.isInteger(high)||low<20||high>600||low>=high){status.textContent='Enter whole numbers from 20 to 600, with low below high.';return;}state.thresholds={low,high};state.contextualEmotes=document.querySelector('#context-enabled').checked;save();root.DiaMealRoutine?.tick();status.textContent='Parent visual preferences saved.';};}
root.DiaCompanionPreferences={card,bind};
})(window);
